#include <stdio.h>
int main(void) {
    int values[4] = {4, 8, 12, 16};
    int length = sizeof(values) / sizeof(int);
    int sum = 0;
    for (int i = 0; i < length; i++) {
        sum += values[i];
    }
    printf("length=%d sum=%d\n", length, sum);
    return 0;
}

#include <stdio.h>
int main(void) {
    int value = 21;
    int *p = &value;
    *p = *p + 21;
    printf("value=%d through_pointer=%d\n", value, *p);
    return 0;
}

#include <stdio.h>
int sum_to(int n) {
    int sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += i;
    }
    return sum;
}
int main(void) {
    int first = sum_to(5);
    int second = sum_to(10);
    printf("first=%d second=%d\n", first, second);
    return 0;
}

