module gate(input a, input b, output y);
    assign y = a & b;
endmodule

module half_adder(input a, input b, output sum, output carry);
    assign sum = a ^ b;
    assign carry = a & b;
endmodule

module mux(input a, input b, input select, output y);
    assign y = select ? b : a;
endmodule

module compare(input [1:0] a, input [1:0] b, output equal, output less);
    assign equal = a == b;
    assign less = a < b;
endmodule
